contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint lockTime, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        (uint beforeCollateral, uint beforeUnlockTime) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        beforeUnlockTime;
        uint beforeContract = address(c).balance;

        bool reverted;
        c.Put{value: amount}(lockTime); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        (uint afterCollateral, uint afterUnlockTime) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        afterUnlockTime;
        uint afterContract = address(c).balance;

        assert(
            reverted
                ? (afterCollateral == beforeCollateral && afterContract == beforeContract)
                : (afterCollateral >= beforeCollateral)
        );
    }

    receive() external payable {}
}

