pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 lockTime, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeCollateral;
        uint256 beforeUnlockTime;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { beforeCollateral = __r0; beforeUnlockTime = __r1; } catch { return; }
        beforeUnlockTime;
        uint beforeContract = address(c).balance;
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCollateral;
        uint256 afterUnlockTime;
        try c.Acc(address(this)) returns (uint256 __r0, uint256 __r1) { afterCollateral = __r0; afterUnlockTime = __r1; } catch { return; }
        afterUnlockTime;
        uint afterContract = address(c).balance;
        assertTrue(reverted
                ? (afterCollateral == beforeCollateral && afterContract == beforeContract)
                : (afterCollateral >= beforeCollateral));
    }

    function testFuzz_run(uint256 lockTime, uint256 amount) public {
        _run(lockTime, amount);
    }

    receive() external payable {}
}
